/* config.h — hand-written Mednafen configuration for the Sapphirine frontend.
 *
 * SPDX-License-Identifier: GPL-3.0-or-later
 *
 * Stand-in for the autogenerated include/config.h, for a build of Mednafen 1.32.1's "ss" module
 * for Android arm64-v8a (LP64, little-endian, bionic libc, API 29+, NDK's zlib). Only what the
 * ss module and the common code it links against use is defined; everything else is left
 * undefined on purpose (other systems, NLS, libFLAC, HAVE_STRERROR_R, ...).
 *
 * Passed via -DHAVE_CONFIG_H; <mednafen/types.h> includes it first in every Mednafen
 * translation unit.
 */

#ifndef __MDFN_SAPPHIRINE_CONFIG_H
#define __MDFN_SAPPHIRINE_CONFIG_H

/* ---- What to build ---- */

/* The Sega Saturn module. */
#define WANT_SS_EMU 1

/* WANT_SSFPLAY_EMU is intentionally not defined: ssf.cpp (SSF playback) is not built.
 * WANT_DEBUGGER and WANT_FANCY_SCALERS stay off; MDFN_ENABLE_DEV_BUILD likewise.
 * No ARCH_X86 / ARCH_POWERPC: types.h detects ARM64 (and picks up NEON) by itself.
 */

/* ---- Version ---- */

#define MEDNAFEN_VERSION "1.32.1"
/* From configure.ac (MEDNAFEN_VERSION_NUMERIC=0x00103201); mednafen.cpp static-asserts it. */
#define MEDNAFEN_VERSION_NUMERIC 0x00103201

/* ---- Endianness ---- */

/* arm64-v8a is always little-endian. types.h errors out unless MSB_FIRST or LSB_FIRST is set. */
#define LSB_FIRST 1

/* ---- Path separator (configure.ac's UNIX branch) ---- */

#define MDFN_PSS_STYLE 1

/* A shared library is always compiled with -fPIC, which types.h warns about
 * (--no-PIC is not an option on Android); the warning is informational only. */
#define MDFN_DISABLE_PICPIE_ERRWARN 1

/* ---- LP64 sizes (aarch64: char 1, short/int 4, long/pointer 8; bionic off_t is 64-bit) ---- */

#define SIZEOF_CHAR 1
#define SIZEOF_SHORT 2
#define SIZEOF_INT 4
#define SIZEOF_LONG 8
#define SIZEOF_LONG_LONG 8
#define SIZEOF_OFF_T 8
#define SIZEOF_PTRDIFF_T 8
#define SIZEOF_SIZE_T 8
#define SIZEOF_VOID_P 8
/* types.h derives HAVE_NATIVE64BIT from SIZEOF_VOID_P >= 8. */

/* ---- Standard headers ---- */

#define STDC_HEADERS 1
#define HAVE_STRING_H 1
#define HAVE_STDINT_H 1
#define HAVE_INTTYPES_H 1
#define HAVE_STDINT_H_WITH_UINTMAX 1
#define HAVE_INTTYPES_H_WITH_UINTMAX 1
#define HAVE_INTMAX_T 1
#define HAVE_UINTMAX_T 1
#define HAVE_LONG_LONG_INT 1
#define HAVE_UNSIGNED_LONG_LONG_INT 1
#define HAVE_FENV_H 1
#define HAVE_LIMITS_H 1
#define HAVE_UNISTD_H 1
#define HAVE_FCNTL_H 1
#define HAVE_STDLIB_H 1
#define HAVE_SYS_PARAM_H 1
#define HAVE_SYS_STAT_H 1
#define HAVE_SYS_TYPES_H 1

/* ---- Functions bionic really has ---- */

#define HAVE_MEMCMP 1
#define HAVE_MEMCPY 1
#define HAVE_MEMMOVE 1
#define HAVE_MEMSET 1
#define HAVE_MKDIR 1
/* POSIX-style mkdir(path, mode); MKDIR_TAKES_ONE_ARG stays undefined. */
#define HAVE_ALLOCA 1
#define HAVE_ALLOCA_H 1
#define HAVE_CLOCK_GETTIME 1
#define HAVE_GMTIME_R 1
#define HAVE_LOCALTIME_R 1
#define HAVE_MMAP 1
#define HAVE_MADVISE 1

/* HAVE_LSEEK64 / HAVE_FSTAT64 / HAVE_FTRUNCATE64 are left out: they matter only when
 * SIZEOF_OFF_T == 4, and off_t is 64-bit here. HAVE_STRERROR_R is left out on purpose:
 * bionic only gives the GNU variant (char* return) under _GNU_SOURCE, and the code
 * (ErrnoHolder) falls back to plain strerror() when it is undefined.
 * HAVE_SIGLONGJMP / HAVE__LONGJMP unused: __USING_SJLJ_EXCEPTIONS__ is not defined, so
 * jump.h only needs them on non-x86_64 GCC targets. */

/* ---- What mthreading/MThreading_POSIX.cpp sees on bionic (each #if in the file checked) ----
 *
 * The VDP2 renderer thread (ss.affinity.vdp2) goes through this file, so the defines below
 * pick its platform branches for Android's libc.
 */
/* sched.h exists on Android (sched_setscheduler/sched_setaffinity/gettid). */
#define HAVE_SCHED_H 1
/* pthread_condattr_setclock() is there; condvars then run on CLOCK_MONOTONIC, so
 * Cond_TimedWait() does not break when wallclock time jumps (NTP, user adjustment). */
#define HAVE_PTHREAD_CONDATTR_SETCLOCK 1
/* sem_timedwait() is there (no version restriction in its header). */
#define HAVE_SEM_TIMEDWAIT 1
/* pthread_setname_np() is there (API 26+), and it is a function, not a macro, so the file's
 * Linux PTSNW overload (pthread_t, const char*) matches bionic's declaration. */
#define HAVE_PTHREAD_SETNAME_NP 1

/* Deliberately NOT defined:
 * - HAVE_SEM_CLOCKWAIT / HAVE_SEM_CLOCKWAIT_NP: sem_clockwait() is API 30+, above minSdk 29
 *   (sem_clockwait_np is glibc/NetBSD-only anyway). Timed semaphore waits therefore use the
 *   CLOCK_REALTIME-based sem_timedwait() branch, which #warns "Using realtime-clock-based
 *   sem_timedwait()" — expected, and fine for the render thread's synchronization.
 * - HAVE_PTHREAD_NP_H: there is no pthread_np.h on bionic.
 * - PTHREAD_AFFINITY_NP: bionic has no pthread_setaffinity_np()/pthread_getaffinity_np(), so
 *   the file compiles its "no affinity support" fallback, which also #warns ("Compiling
 *   without affinity setting support."). Upstream's fallback throws for any non-zero mask;
 *   that is OK: ss.affinity.vdp2 defaults to 0, and a 0 mask is never passed through.
 */

#endif /* __MDFN_SAPPHIRINE_CONFIG_H */
